  'events.runbook.nodePolicyEnforced': 'Review Settings for maintenance, max sessions, or bandwidth caps before changing the Rust node. These are expected policy blocks, not packet inspection.',
  'events.runbook.nodePolicySyncPending': 'The backend policy differs from the Rust runtime snapshot, or the node has not reported a policy snapshot yet. Open Node Detail to check Policy Sync and wait for the next heartbeat before assuming the setting is enforced.',
  'events.runbook.runtimeRecovery': 'The Rust process recovered after restart and stale active sessions were closed. Open Node Detail, check Runtime Recovery, active sessions, Policy Sync, and recent command lifecycle before deciding whether to keep maintenance mode on or restart again.',
  'events.runbook.runtimeRestarted': 'A recent Rust process restart was observed. Watch active sessions, Policy Sync, and Runtime Recovery for the next heartbeat cycle before taking disruptive action.',
  'events.runbook.clientPlacementUnavailable': 'This public AeroNyx node is hidden from the client server list because of {reason}. Open Node Detail Client Placement, Health, Policy Sync, and Settings before expecting new clients to receive it.',
  'events.runbook.placementCapacity': 'Client placement capacity is constrained for {label} {scope}. Check Nodes > Client Placement for region/tier capacity, then add capacity, lower load, end maintenance, or move traffic. Top unavailable reason: {reason}.',
  'events.runbook.bandwidthLimitPressure': 'Check whether the node is intentionally capped in Settings. Increase bandwidth_limit_mbps or move traffic to another region/tier if paid users are affected.',
  'events.runbook.nodePolicyChanged': 'Use this audit trail to confirm who changed placement, tier, maintenance, session caps, bandwidth, or heartbeat policy before correlating later health events.',
  'events.runbook.sessionKeepaliveTimeout': 'Keepalive ACK loss means the tunnel can be established while responsiveness is failing. Check node bandwidth pressure and heartbeat freshness, then kick the affected session if missed ACKs continue.',
  'events.runbook.applyPolicy': 'Policy acknowledgement confirms the Rust node has received the latest nodeboard policy snapshot. If it stays pending, open Node Detail and compare Policy Sync after the next heartbeat.',
  'events.runbook.sessionDegradedKeepalive': 'Keepalive degradation usually means tunnel ACKs are delayed or missing. Compare missed and pending counters before deciding whether to kick the session or move traffic.',
  'events.runbook.sessionDegradedRtt': 'High RTT usually points to route congestion or bad regional placement. Compare the node region with the user cohort and check bandwidth pressure events.',
  'events.runbook.sessionDegradedTraffic': 'Stale RX/TX usually means the tunnel stopped carrying traffic. Check node heartbeat freshness, then use AeroNyx Operations to kick the affected session if it remains active.',
  'events.runbook.sessionDegradedGeneric': 'Open AeroNyx Operations to identify the affected session, virtual IP, last activity, RTT, and packet loss before deciding whether to kick or ban.',
  'events.runbook.nodeCommand': 'Open Node Detail command history for lifecycle timing and structured output. Retry only after the previous command is completed, failed, cancelled, or timed out.',
  'events.runbook.dnsFailure': 'DNS failure usually breaks browsing while the tunnel is up. Use Collect Logs on Node Detail, then check local resolver and firewall configuration on the node.',
  'events.runbook.natFailure': 'NAT or forwarding failure means clients can connect but cannot exit to the Internet. Check forwarding/NAT config and consider maintenance mode while fixing.',
  'events.runbook.tunFailure': 'TUN or MTU failure points to local AeroNyx interface configuration. Use System Info and Collect Logs, then restart AeroNyx only if diagnostics confirm the service is wedged.',
  'events.runbook.egressFailure': 'Egress failure means the node cannot reach the Internet. Move traffic away from this node and verify provider networking before accepting new sessions.',
  'events.runbook.udpListenerFailure': 'UDP listener failure means new clients cannot connect. Check service status from Node Detail and use Restart AeroNyx if the process is unhealthy.',
  'events.runbook.criticalDefault': 'Start with Node Detail health checks, then use maintenance mode to stop new handshakes while you confirm whether active sessions are affected.',
  'events.runbook.warningDefault': 'Correlate this warning with recent Settings audits, session quality, and policy enforcement before taking disruptive action.',
